-- Explicit bounded refund-success event commissioning. No business DML or grants.
SET LOCAL search_path TO pg_catalog, public, pg_temp;
SELECT set_config('statement_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_settings WHERE name='statement_timeout'),0),5000)::text||'ms',true),
 set_config('lock_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_settings WHERE name='lock_timeout'),0),1000)::text||'ms',true);
DO $refund_success_notice$
DECLARE d text; old_comment text; safe boolean; n integer; events text;
BEGIN
 LOCK TABLE ONLY public.store_order_outbox IN ACCESS EXCLUSIVE MODE NOWAIT;
 SELECT q.definition,q.safe INTO d,safe FROM (SELECT pg_get_constraintdef(k.oid,false) AS definition,
  k.contype='c' AND k.convalidated AND NOT k.condeferrable AND NOT k.condeferred
  AND NOT k.connoinherit AND k.conislocal AND k.coninhcount=0 AND k.conkey=ARRAY[a.attnum]::smallint[]
  AND a.atttypid='pg_catalog.varchar'::regtype AND a.atttypmod=68 AND a.attnotnull
  AND a.attgenerated='' AND a.attidentity='' AND NOT a.atthasdef AND NOT a.attisdropped
  AND a.attcollation='pg_catalog."default"'::regcollation
  AND c.relkind='r' AND c.relpersistence='p' AND NOT c.relispartition AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity
  AND pg_catalog.to_regclass('store_order_outbox')=c.oid
  AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhparent=c.oid OR inhrelid=c.oid)
  AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_event_trigger WHERE evtenabled<>'D') AS safe
 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_constraint k ON k.conrelid=c.oid AND k.conname='soob_event_type_ck'
 JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attname='event_type'
 WHERE c.oid=pg_catalog.to_regclass('public.store_order_outbox')) q;
 IF safe IS DISTINCT FROM true THEN RAISE EXCEPTION 'Refund success outbox catalog drift'; END IF;
 SELECT obj_description(oid,'pg_constraint') INTO old_comment FROM pg_constraint
  WHERE conrelid='public.store_order_outbox'::regclass AND conname='soob_event_type_ck';
 IF d IN ('CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''order.refund.success.notice''::character varying])::text[])))','CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''order.price.revision''::character varying, ''order.refund.success.notice''::character varying])::text[])))','CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying, ''order.refund.success.notice''::character varying])::text[])))','CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''order.price.revision''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying, ''order.refund.success.notice''::character varying])::text[])))') THEN RETURN; END IF;
 CASE d
 WHEN 'CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying])::text[])))' THEN events:='''order.paid'',''order.delivery.notice'',''order.refund.refused.notice'',''order.second_card.advent.notice'',''order.second_card.expired.notice'',''withdrawal.approved.notice'',''withdrawal.refused.notice'',''withdrawal.applied.notice'',''withdrawal.staff.refresh'',''order.presale.fulfillment'',''order.pink.success.notice'',''product.stock.effects'',''product.recycle.effects'',''product.save.effects'',''order.refund.success.notice''';
 WHEN 'CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''order.price.revision''::character varying])::text[])))' THEN events:='''order.paid'',''order.delivery.notice'',''order.refund.refused.notice'',''order.second_card.advent.notice'',''order.second_card.expired.notice'',''withdrawal.approved.notice'',''withdrawal.refused.notice'',''withdrawal.applied.notice'',''withdrawal.staff.refresh'',''order.presale.fulfillment'',''order.pink.success.notice'',''product.stock.effects'',''product.recycle.effects'',''product.save.effects'',''order.price.revision'',''order.refund.success.notice''';
 WHEN 'CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying])::text[])))' THEN events:='''order.paid'',''order.delivery.notice'',''order.refund.refused.notice'',''order.second_card.advent.notice'',''order.second_card.expired.notice'',''withdrawal.approved.notice'',''withdrawal.refused.notice'',''withdrawal.applied.notice'',''withdrawal.staff.refresh'',''order.presale.fulfillment'',''order.pink.success.notice'',''product.stock.effects'',''product.recycle.effects'',''product.save.effects'',''recharge.paid.shipping'',''membership.paid.shipping'',''order.refund.success.notice''';
 WHEN 'CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''order.price.revision''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying])::text[])))' THEN events:='''order.paid'',''order.delivery.notice'',''order.refund.refused.notice'',''order.second_card.advent.notice'',''order.second_card.expired.notice'',''withdrawal.approved.notice'',''withdrawal.refused.notice'',''withdrawal.applied.notice'',''withdrawal.staff.refresh'',''order.presale.fulfillment'',''order.pink.success.notice'',''product.stock.effects'',''product.recycle.effects'',''product.save.effects'',''order.price.revision'',''recharge.paid.shipping'',''membership.paid.shipping'',''order.refund.success.notice''';
 ELSE RAISE EXCEPTION 'Refund success outbox predecessor drift; no automatic repair';
 END CASE;
 SELECT count(*) INTO n FROM (SELECT 1 FROM public.store_order_outbox LIMIT 10001) bounded;
 IF n>10000 THEN RAISE EXCEPTION 'Refund success outbox maintenance row budget exceeded'; END IF;
 ALTER TABLE public.store_order_outbox DROP CONSTRAINT soob_event_type_ck;
 EXECUTE 'ALTER TABLE public.store_order_outbox ADD CONSTRAINT soob_event_type_ck CHECK(event_type IN ('||events||'))';
 IF old_comment IS NOT NULL THEN EXECUTE format('COMMENT ON CONSTRAINT soob_event_type_ck ON public.store_order_outbox IS %L',old_comment); END IF;
END
$refund_success_notice$;
